  "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>devtoolkit — 开发者工作台</title>\n<style>\n  :root {\n    --bg: #090b10;\n    --card-bg: rgba(18, 22, 31, 0.85);\n    --border: rgba(255, 255, 255, 0.08);\n    --border-hover: rgba(59, 130, 246, 0.4);\n    --text-primary: #f8fafc;\n    --text-secondary: #94a3b8;\n    --text-muted: #64748b;\n    --accent: #3b82f6;\n    --accent-glow: rgba(59, 130, 246, 0.2);\n    --accent-hover: #60a5fa;\n    --purple: #a855f7;\n    --purple-glow: rgba(168, 85, 247, 0.15);\n    --green: #10b981;\n    --red: #ef4444;\n    --yellow: #f59e0b;\n    --radius: 12px;\n    --radius-sm: 8px;\n    --font: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, \"PingFang SC\", \"Hiragino Sans GB\", \"Microsoft YaHei\", sans-serif;\n    --mono: SFMono-Regular, Consolas, Menlo, monospace;\n  }\n\n  * { margin: 0; padding: 0; box-sizing: border-box; }\n  \n  body {\n    font-family: var(--font);\n    background: var(--bg);\n    color: var(--text-primary);\n    min-height: 100vh;\n    line-height: 1.5;\n    -webkit-font-smoothing: antialiased;\n    background-image: \n      radial-gradient(at 0% 0%, rgba(59, 130, 246, 0.07) 0px, transparent 50%),\n      radial-gradient(at 100% 100%, rgba(168, 85, 247, 0.07) 0px, transparent 50%);\n    background-attachment: fixed;\n  }\n\n  .container { max-width: 1060px; margin: 0 auto; padding: 32px 24px 80px; }\n  header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 32px; padding-bottom: 20px; border-bottom: 1px solid var(--border); }\n  .logo-area { display: flex; align-items: center; gap: 12px; }\n  .logo-icon { width: 40px; height: 40px; border-radius: 10px; background: linear-gradient(135deg, #3b82f6 0%, #8b5cf6 100%); display: flex; align-items: center; justify-content: center; font-size: 20px; box-shadow: 0 4px 16px rgba(59,130,246,0.3); }\n  .logo-text h1 { font-size: 20px; font-weight: 700; color: #fff; }\n  .logo-text p { font-size: 12px; color: var(--text-muted); font-weight: 500; }\n  \n  .tab-nav { display: flex; background: rgba(18, 22, 31, 0.9); padding: 4px; border-radius: 10px; border: 1px solid var(--border); gap: 4px; flex-wrap: wrap; }\n  .tab-btn { padding: 8px 16px; background: transparent; border: none; border-radius: 8px; color: var(--text-secondary); font-size: 13px; font-weight: 600; cursor: pointer; transition: all 0.2s; display: flex; align-items: center; gap: 6px; }\n  .tab-btn:hover { color: var(--text-primary); }\n  .tab-btn.active { background: var(--accent); color: #fff; box-shadow: 0 2px 10px rgba(59, 130, 246, 0.4); }\n\n  .card { background: var(--card-bg); border: 1px solid var(--border); border-radius: var(--radius); padding: 24px; margin-bottom: 24px; }\n  .card:hover { border-color: rgba(255, 255, 255, 0.12); }\n  .card-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 20px; }\n  .card-title { font-size: 16px; font-weight: 600; color: #fff; display: flex; align-items: center; gap: 8px; }\n  \n  .form-group { margin-bottom: 18px; }\n  label { display: block; font-size: 13px; font-weight: 600; margin-bottom: 8px; color: var(--text-secondary); }\n  input[type=\"text\"], input[type=\"password\"], select, textarea {\n    width: 100%; padding: 12px 14px; background: rgba(10, 13, 18, 0.75);\n    border: 1px solid var(--border); border-radius: var(--radius-sm); color: var(--text-primary);\n    font-size: 14px; font-family: inherit; transition: all 0.2s;\n  }\n  input:focus, select:focus, textarea:focus { outline: none; border-color: var(--accent); box-shadow: 0 0 0 3px var(--accent-glow); }\n  textarea { min-height: 80px; resize: vertical; line-height: 1.6; }\n  .row { display: flex; gap: 16px; }\n  .row .form-group { flex: 1; }\n\n  .btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; padding: 11px 22px; border: none; border-radius: var(--radius-sm); font-size: 14px; font-weight: 600; cursor: pointer; transition: all 0.2s; user-select: none; }\n  .btn-primary { background: linear-gradient(135deg, #3b82f6 0%, #2563eb 100%); color: #fff; box-shadow: 0 2px 12px rgba(37, 99, 235, 0.3); }\n  .btn-primary:hover { background: linear-gradient(135deg, #60a5fa 0%, #3b82f6 100%); }\n  .btn-primary:disabled { opacity: 0.5; cursor: not-allowed; }\n  .btn-secondary { background: rgba(255, 255, 255, 0.05); color: var(--text-primary); border: 1px solid var(--border); }\n  .btn-secondary:hover { background: rgba(255, 255, 255, 0.1); }\n  .btn-success { background: linear-gradient(135deg, #10b981 0%, #059669 100%); color: #fff; }\n  .btn-sm { padding: 7px 14px; font-size: 13px; border-radius: 6px; }\n\n  .upload-zone { border: 2px dashed rgba(255, 255, 255, 0.12); border-radius: var(--radius); padding: 32px 20px; text-align: center; cursor: pointer; transition: all 0.2s; background: rgba(10, 13, 18, 0.5); margin-bottom: 16px; }\n  .upload-zone:hover { border-color: var(--accent); background: var(--accent-glow); }\n  .upload-zone .icon { font-size: 32px; margin-bottom: 8px; }\n  .upload-zone .text { font-size: 14px; color: var(--text-secondary); }\n  .upload-zone .file-name { font-size: 13px; color: var(--green); font-weight: 600; margin-top: 8px; }\n\n  .status { padding: 12px 16px; border-radius: var(--radius-sm); font-size: 13px; margin-bottom: 18px; display: none; }\n  .status.show { display: block; }\n  .status.info { background: rgba(59, 130, 246, 0.12); color: var(--accent-hover); border: 1px solid rgba(59, 130, 246, 0.3); }\n  .status.error { background: rgba(239, 68, 68, 0.12); color: #fca5a5; border: 1px solid rgba(239, 68, 68, 0.3); }\n  .status.success { background: rgba(16, 185, 129, 0.12); color: #6ee7b7; border: 1px solid rgba(16, 185, 129, 0.3); }\n\n  .stats-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 14px; margin-bottom: 20px; }\n  .stat-card { background: rgba(10, 13, 18, 0.7); border: 1px solid var(--border); border-radius: var(--radius-sm); padding: 14px 16px; }\n  .stat-card .label { font-size: 12px; color: var(--text-muted); font-weight: 500; }\n  .stat-card .num { font-size: 20px; font-weight: 700; color: #fff; margin-top: 4px; }\n\n  .code-box { background: #06080c; border: 1px solid var(--border); border-radius: var(--radius-sm); padding: 14px 16px; font-family: var(--mono); font-size: 13px; line-height: 1.6; color: #e2e8f0; overflow-x: auto; white-space: pre; }\n  .search-item { background: rgba(10, 13, 18, 0.7); border: 1px solid var(--border); border-radius: var(--radius-sm); padding: 16px; margin-bottom: 14px; transition: all 0.2s; }\n  .search-item:hover { border-color: var(--accent); }\n  .search-item-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px; }\n  .file-badge { font-family: var(--mono); font-size: 13px; font-weight: 600; color: var(--accent-hover); }\n  .score-badge { font-size: 12px; padding: 2px 10px; border-radius: 20px; background: var(--accent-glow); color: var(--accent-hover); font-weight: 600; }\n  .tag { display: inline-block; font-size: 11px; padding: 2px 8px; border-radius: 4px; background: rgba(255, 255, 255, 0.06); color: var(--text-secondary); margin-right: 6px; font-family: var(--mono); }\n  .quick-tags { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 8px; }\n  .quick-tag { font-size: 11px; padding: 3px 10px; border-radius: 20px; background: rgba(59, 130, 246, 0.08); color: var(--accent-hover); cursor: pointer; border: 1px solid rgba(59, 130, 246, 0.2); transition: all 0.15s; font-family: var(--mono); }\n  .quick-tag:hover { background: var(--accent); color: #fff; }\n\n  /* 架构图谱模块与代码联动 */\n  .module-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 16px; margin-top: 16px; }\n  .module-card { background: rgba(10, 13, 18, 0.85); border: 1px solid var(--border); border-radius: var(--radius-sm); padding: 16px; transition: all 0.2s; }\n  .module-card.dimmed { opacity: 0.35; filter: grayscale(0.5); }\n  .module-card.highlighted { border-color: var(--accent); box-shadow: 0 0 16px var(--accent-glow); }\n  .module-header { font-size: 14px; font-weight: 700; color: var(--accent-hover); margin-bottom: 10px; display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid rgba(255,255,255,0.06); padding-bottom: 6px; }\n  .node-item { display: flex; justify-content: space-between; align-items: center; padding: 7px 10px; border-radius: 6px; font-family: var(--mono); font-size: 12px; cursor: pointer; transition: all 0.15s; margin-bottom: 4px; border: 1px solid transparent; }\n  .node-item:hover { background: rgba(59, 130, 246, 0.15); border-color: rgba(59, 130, 246, 0.3); }\n  .node-item.selected { background: var(--accent); color: #fff; font-weight: 700; }\n  .node-item.dep-node { border-color: var(--green); background: rgba(16, 185, 129, 0.1); }\n  .node-item.upstream-node { border-color: var(--purple); background: rgba(168, 85, 247, 0.1); }\n\n  /* 交互式关联卡片与源码查看器 */\n  .dep-detail-box { background: rgba(10, 13, 18, 0.95); border: 1px solid var(--accent); border-radius: var(--radius); padding: 20px; margin-top: 16px; display: none; animation: fadeIn 0.15s ease-in; }\n  .link-pill { display: inline-flex; align-items: center; gap: 4px; font-size: 11px; padding: 3px 8px; border-radius: 4px; background: rgba(59, 130, 246, 0.15); color: var(--accent-hover); cursor: pointer; margin: 3px 4px 3px 0; border: 1px solid rgba(59, 130, 246, 0.3); font-family: var(--mono); transition: all 0.15s; }\n  .link-pill:hover { background: var(--accent); color: #fff; }\n</style>\n</head>\n<body>\n<div class=\"container\">\n  <header>\n    <div class=\"logo-area\">\n      <div class=\"logo-icon\">⚡</div>\n      <div class=\"logo-text\">\n        <h1>devtoolkit <span style=\"font-size:14px; font-weight:500; color:var(--accent);\">Dashboard</span></h1>\n        <p>AI 技能生成 · 规则互转 · 效果评测 · 代码依赖拓扑 · 环境资产</p>\n      </div>\n    </div>\n    <div class=\"tab-nav\">\n      <button type=\"button\" class=\"tab-btn active\" id=\"tabBtnSkills\">📄 技能工坊</button>\n      <button type=\"button\" class=\"tab-btn\" id=\"tabBtnConvert\">🔄 规则互转</button>\n      <button type=\"button\" class=\"tab-btn\" id=\"tabBtnSearch\">🔍 代码搜索</button>\n      <button type=\"button\" class=\"tab-btn\" id=\"tabBtnGraph\">📈 架构图谱</button>\n      <button type=\"button\" class=\"tab-btn\" id=\"tabBtnEnv\">📦 环境资产</button>\n    </div>\n  </header>\n\n  <!-- TAB 1: 技能工坊 -->\n  <div id=\"panel-skills\">\n    <div class=\"card\">\n      <div class=\"card-header\"><div class=\"card-title\">📄 文档转 AI 技能包 (Doc2Skill / OpenAPI)</div></div>\n      <div id=\"skillStatus\" class=\"status\"></div>\n\n      <div class=\"upload-zone\" id=\"uploadZone\">\n        <div class=\"icon\">📁</div>\n        <div class=\"text\">点击或拖拽文档到此处（支持 .md / .txt / .pdf / .docx / .html / openapi.json）</div>\n        <div class=\"file-name\" id=\"fileNameDisplay\"></div>\n        <input type=\"file\" id=\"fileInput\" style=\"display:none\" accept=\".md,.markdown,.txt,.text,.html,.htm,.pdf,.docx,.json,.yaml,.yml\">\n      </div>\n\n      <div class=\"form-group\">\n        <label>或输入在线文档 / OpenAPI Swagger URL / 纯文本内容：</label>\n        <textarea id=\"sourceInput\" placeholder=\"输入在线文档 URL (如 https://petstore.swagger.io/v2/swagger.json 或 API 文档)\"></textarea>\n      </div>\n\n      <div class=\"row\">\n        <div class=\"form-group\">\n          <label>目标 Agent：</label>\n          <select id=\"agentType\">\n            <option value=\"codex\">🤖 Codex (.agents/skills/)</option>\n            <option value=\"cursor\">🎯 Cursor (.cursor/rules/)</option>\n            <option value=\"claude\">🧠 Claude (CLAUDE.md)</option>\n          </select>\n        </div>\n        <div class=\"form-group\">\n          <label>预设模板：</label>\n          <select id=\"templateSelect\"><option value=\"\">自动提炼 (通用标准)</option></select>\n        </div>\n        <div class=\"form-group\">\n          <label>技能名称 (可选)：</label>\n          <input type=\"text\" id=\"skillNameInput\" placeholder=\"默认从文档标题自动提取\">\n        </div>\n      </div>\n\n      <div class=\"row\">\n        <div class=\"form-group\">\n          <label>LLM 模型：</label>\n          <select id=\"modelSelect\"></select>\n        </div>\n        <div class=\"form-group\" id=\"apiKeyGroup\">\n          <label>API Key：</label>\n          <input type=\"password\" id=\"apiKeyInput\" placeholder=\"留空使用服务端默认环境变量\">\n        </div>\n      </div>\n\n      <div id=\"localConfig\" style=\"display:none; margin-bottom:18px; padding:16px; background:rgba(10,13,18,0.7); border:1px solid var(--border); border-radius:var(--radius-sm);\">\n        <div class=\"row\">\n          <div class=\"form-group\">\n            <label>本地服务地址：</label>\n            <input type=\"text\" id=\"localBaseUrl\" value=\"http://localhost:11434\">\n          </div>\n          <div class=\"form-group\" style=\"flex:0 0 130px; align-self:flex-end;\">\n            <button type=\"button\" class=\"btn btn-secondary\" id=\"detectBtn\" style=\"width:100%\">🔍 探测模型</button>\n          </div>\n          <div class=\"form-group\">\n            <label>选择/输入模型：</label>\n            <select id=\"localModelSelect\" style=\"display:none\"></select>\n            <input type=\"text\" id=\"localModelInput\" placeholder=\"输入模型名 (如 qwen2.5-coder:7b)\">\n          </div>\n        </div>\n      </div>\n\n      <div style=\"display:flex; gap:12px; margin-top:10px;\">\n        <button type=\"button\" class=\"btn btn-primary\" id=\"generateBtn\">🚀 开始提炼技能包</button>\n      </div>\n    </div>\n\n    <div class=\"card\" id=\"skillResultCard\" style=\"display:none\">\n      <div class=\"card-header\">\n        <div class=\"card-title\">✨ 生成结果预览</div>\n        <div style=\"display:flex; gap:10px;\">\n          <button type=\"button\" class=\"btn btn-primary btn-sm\" id=\"evalSkillBtn\">📊 技能效果自动化评测</button>\n          <button type=\"button\" class=\"btn btn-success btn-sm\" id=\"downloadZipBtn\">📦 下载完整 ZIP</button>\n          <button type=\"button\" class=\"btn btn-secondary btn-sm\" id=\"copySkillBtn\">📋 复制内容</button>\n        </div>\n      </div>\n      <div id=\"skillStats\" class=\"stats-grid\"></div>\n      <div class=\"code-box\" id=\"skillContentPreview\" style=\"max-height:480px\"></div>\n    </div>\n\n    <div class=\"card\" id=\"skillEvalCard\" style=\"display:none; border-color:rgba(168,85,247,0.4); background:var(--purple-glow);\">\n      <div class=\"card-header\">\n        <div class=\"card-title\" style=\"color:var(--purple)\">📊 AI 技能效果评测报告</div>\n      </div>\n      <div class=\"code-box\" id=\"skillEvalPreview\" style=\"max-height:360px\"></div>\n    </div>\n  </div>\n\n  <!-- TAB 2: 规则互转与同步 -->\n  <div id=\"panel-convert\" style=\"display:none;\">\n    <div class=\"card\">\n      <div class=\"card-header\">\n        <div class=\"card-title\">🔄 跨 Agent 规则无损互转与全量同步</div>\n      </div>\n      <div id=\"convertStatus\" class=\"status\"></div>\n\n      <div class=\"form-group\">\n        <label>粘贴规则 Markdown 或带有 YAML Frontmatter 的规则：</label>\n        <textarea id=\"convertInput\" placeholder=\"例如粘贴 .cursor/rules/*.mdc、.agents/skills/*/SKILL.md 或 CLAUDE.md 内容...\"></textarea>\n      </div>\n\n      <div class=\"row\">\n        <div class=\"form-group\">\n          <label>转换目标 Agent：</label>\n          <select id=\"convertToSelect\">\n            <option value=\"codex\">🤖 转换为 Codex 官方技能 (.agents/skills/)</option>\n            <option value=\"cursor\">🎯 转换为 Cursor 官方规则 (.cursor/rules/*.mdc)</option>\n            <option value=\"claude\">🧠 转换为 Claude Code 规则 (CLAUDE.md)</option>\n          </select>\n        </div>\n        <div class=\"form-group\">\n          <label>规则名称 (可选)：</label>\n          <input type=\"text\" id=\"convertNameInput\" placeholder=\"默认从原内容自动提取\">\n        </div>\n      </div>\n\n      <div style=\"display:flex; justify-content:space-between; align-items:center; margin-top:8px;\">\n        <button type=\"button\" class=\"btn btn-primary\" id=\"startConvertBtn\">⚡ 立即转换格式</button>\n        <button type=\"button\" class=\"btn btn-secondary\" id=\"syncProjectBtn\">🔄 一键扫描并全量同步项目规则</button>\n      </div>\n    </div>\n\n    <div class=\"card\" id=\"convertResultCard\" style=\"display:none\">\n      <div class=\"card-header\">\n        <div class=\"card-title\">✨ 转换产物预览</div>\n        <button type=\"button\" class=\"btn btn-secondary btn-sm\" id=\"copyConvertBtn\">📋 复制转换结果</button>\n      </div>\n      <div class=\"code-box\" id=\"convertPreview\" style=\"max-height:400px\"></div>\n    </div>\n  </div>\n\n  <!-- TAB 3: 代码搜索与影响面 -->\n  <div id=\"panel-search\" style=\"display:none;\">\n    <div class=\"card\">\n      <div class=\"card-header\">\n        <div class=\"card-title\">🔍 代码语义搜索与影响面推演</div>\n        <button type=\"button\" class=\"btn btn-secondary btn-sm\" id=\"rebuildIndexBtn\">🔄 重建本地索引</button>\n      </div>\n      <div id=\"searchStatus\" class=\"status\"></div>\n\n      <div class=\"row\">\n        <div class=\"form-group\" style=\"flex:2.2;\">\n          <label>自然语言搜索代码：</label>\n          <input type=\"text\" id=\"searchQueryInput\" placeholder=\"输入搜索内容，如 '用户登录认证' 或 'buildIndex'\">\n          <div class=\"quick-tags\">\n            <span style=\"font-size:11px; color:var(--text-muted); align-self:center;\">快捷过滤:</span>\n            <span class=\"quick-tag\" data-filter=\"path:src/\">path:src/</span>\n            <span class=\"quick-tag\" data-filter=\"lang:ts\">lang:ts</span>\n            <span class=\"quick-tag\" data-filter=\"lang:py\">lang:py</span>\n            <span class=\"quick-tag\" data-filter=\"kind:class\">kind:class</span>\n            <span class=\"quick-tag\" data-filter=\"kind:func\">kind:func</span>\n          </div>\n        </div>\n        <div class=\"form-group\" style=\"flex:1;\">\n          <label>项目目录：</label>\n          <input type=\"text\" id=\"searchDirInput\" placeholder=\"留空使用当前目录\">\n        </div>\n      </div>\n\n      <div style=\"display:flex; justify-content:space-between; align-items:center; margin-top:10px;\">\n        <label style=\"display:flex; align-items:center; gap:8px; cursor:pointer; font-size:13px; margin-bottom:0\">\n          <input type=\"checkbox\" id=\"searchExplainCheck\" checked>\n          <span>🤖 开启 LLM 中文智能分析与代码导航建议</span>\n        </label>\n        <div style=\"display:flex; gap:10px;\">\n          <button type=\"button\" class=\"btn btn-secondary\" id=\"impactBtn\">🎯 分析改动影响面</button>\n          <button type=\"button\" class=\"btn btn-primary\" id=\"searchBtn\">🔎 搜索代码</button>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"card\" id=\"searchExplainCard\" style=\"display:none; border-color:rgba(168,85,247,0.3); background:var(--purple-glow);\">\n      <h3 style=\"font-size:14px; font-weight:600; color:var(--purple); margin-bottom:10px;\">🤖 LLM 智能解释与导航建议</h3>\n      <div id=\"searchExplanation\" style=\"font-size:13px; line-height:1.7; white-space:pre-wrap; color:var(--text-primary);\"></div>\n    </div>\n\n    <div class=\"card\" id=\"impactResultCard\" style=\"display:none;\">\n      <div class=\"card-header\"><div class=\"card-title\">🎯 递归影响面推演结果</div></div>\n      <div class=\"code-box\" id=\"impactReportText\" style=\"max-height:300px\"></div>\n    </div>\n\n    <div id=\"searchResultsArea\"></div>\n  </div>\n\n  <!-- TAB 4: 架构依赖图谱与源码穿梭 -->\n  <div id=\"panel-graph\" style=\"display:none;\">\n    <div class=\"card\">\n      <div class=\"card-header\">\n        <div class=\"card-title\">📈 项目架构依赖拓扑与代码联动大盘</div>\n        <div style=\"display:flex; gap:10px;\">\n          <button type=\"button\" class=\"btn btn-secondary btn-sm\" id=\"toggleGraphViewBtn\">📝 切换为 Mermaid 源码</button>\n          <button type=\"button\" class=\"btn btn-primary btn-sm\" id=\"refreshGraphBtn\">🔄 重新扫描分析</button>\n        </div>\n      </div>\n      <div id=\"graphStatus\" class=\"status\"></div>\n      <div id=\"graphStats\" class=\"stats-grid\"></div>\n\n      <!-- 选中文件的关联拓扑与源码查看器 -->\n      <div class=\"dep-detail-box\" id=\"nodeDetailCard\">\n        <div style=\"display:flex; justify-content:space-between; align-items:center; margin-bottom:12px;\">\n          <div style=\"display:flex; align-items:center; gap:8px;\">\n            <div id=\"detailNodeTitle\" style=\"font-weight:700; color:var(--accent-hover); font-family:var(--mono); font-size:14px;\"></div>\n            <span id=\"detailFileStats\" style=\"font-size:11px; color:var(--text-muted); font-family:var(--mono);\"></span>\n          </div>\n          <div style=\"display:flex; gap:8px;\">\n            <button type=\"button\" class=\"btn btn-secondary btn-sm\" id=\"trackImpactFromGraphBtn\">🎯 追踪改动影响面</button>\n            <button type=\"button\" class=\"btn btn-secondary btn-sm\" id=\"copySourceCodeBtn\">📋 复制源码</button>\n            <button type=\"button\" class=\"btn btn-secondary btn-sm\" id=\"closeDetailBtn\" style=\"padding:4px 10px;\">✕</button>\n          </div>\n        </div>\n\n        <div class=\"row\" style=\"margin-bottom:14px;\">\n          <div style=\"flex:1\">\n            <div style=\"font-size:12px; color:var(--green); font-weight:600; margin-bottom:6px;\">➜ 依赖的目标模块 (Dependencies - 点击可跳转):</div>\n            <div id=\"detailDepsPills\" style=\"min-height:30px; display:flex; flex-wrap:wrap; align-items:center;\"></div>\n          </div>\n          <div style=\"flex:1\">\n            <div style=\"font-size:12px; color:var(--purple); font-weight:600; margin-bottom:6px;\">⬅ 被调用的上游模块 (Dependents - 点击可跳转):</div>\n            <div id=\"detailUpstreamsPills\" style=\"min-height:30px; display:flex; flex-wrap:wrap; align-items:center;\"></div>\n          </div>\n        </div>\n\n        <div>\n          <div style=\"font-size:12px; color:var(--text-muted); margin-bottom:6px; font-weight:600;\">💻 模块实时源码 (Code Viewer):</div>\n          <div class=\"code-box\" id=\"sourceCodeViewer\" style=\"max-height:340px;\">加载源码中...</div>\n        </div>\n      </div>\n\n      <!-- 可视化模块卡片网格 -->\n      <div id=\"visualModulesContainer\" class=\"module-grid\"></div>\n\n      <!-- Mermaid 源码展示区 (默认隐藏) -->\n      <div id=\"mermaidSourceContainer\" style=\"display:none; margin-top:16px;\">\n        <div style=\"display:flex; justify-content:space-between; align-items:center; margin-bottom:8px;\">\n          <span style=\"font-size:13px; color:var(--text-muted)\">Mermaid 规范代码：</span>\n          <button type=\"button\" class=\"btn btn-secondary btn-sm\" id=\"copyMermaidBtn\">📋 复制 Mermaid 代码</button>\n        </div>\n        <div class=\"code-box\" id=\"graphMermaidCode\" style=\"max-height:460px\"></div>\n      </div>\n    </div>\n  </div>\n\n  <!-- TAB 5: 环境资产 -->\n  <div id=\"panel-env\" style=\"display:none;\">\n    <div class=\"card\">\n      <div class=\"card-header\">\n        <div class=\"card-title\">📦 当前开发环境资产概览</div>\n        <div style=\"display:flex; gap:10px;\">\n          <button type=\"button\" class=\"btn btn-primary btn-sm\" id=\"refreshEnvBtn\">🔍 扫描/刷新</button>\n          <button type=\"button\" class=\"btn btn-secondary btn-sm\" id=\"exportEnvBtn\">📤 导出快照</button>\n        </div>\n      </div>\n      <div id=\"envStatus\" class=\"status\"></div>\n      <div id=\"envSystemStats\" class=\"stats-grid\"></div>\n\n      <div class=\"row\">\n        <div class=\"form-group\">\n          <label>🍺 Homebrew 软件包：</label>\n          <div class=\"code-box\" id=\"envBrewList\" style=\"max-height:220px; overflow-y:auto;\">点击扫描获取...</div>\n        </div>\n        <div class=\"form-group\">\n          <label>📦 npm 全局包：</label>\n          <div class=\"code-box\" id=\"envNpmList\" style=\"max-height:220px; overflow-y:auto;\">点击扫描获取...</div>\n        </div>\n      </div>\n\n      <div class=\"row\">\n        <div class=\"form-group\">\n          <label>🐍 Python pip 依赖：</label>\n          <div class=\"code-box\" id=\"envPipList\" style=\"max-height:220px; overflow-y:auto;\">点击扫描获取...</div>\n        </div>\n        <div class=\"form-group\">\n          <label>🖥️ VSCode 扩展：</label>\n          <div class=\"code-box\" id=\"envVscodeList\" style=\"max-height:220px; overflow-y:auto;\">点击扫描获取...</div>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"card\">\n      <h2 style=\"font-size:16px; font-weight:600; color:#fff; margin-bottom:12px;\">📊 环境快照差异比对 (Diff)</h2>\n      <div class=\"form-group\">\n        <label>粘贴快照 JSON 进行实时差异比对：</label>\n        <textarea id=\"diffJsonInput\" placeholder=\"粘贴 devtoolkit-env.json 的内容...\"></textarea>\n      </div>\n      <button type=\"button\" class=\"btn btn-secondary\" id=\"diffEnvBtn\">比对环境差异</button>\n      <div id=\"envDiffResult\" style=\"margin-top:16px; display:none;\">\n        <div class=\"code-box\" id=\"envDiffPreview\" style=\"max-height:300px; overflow-y:auto; white-space:pre-wrap;\"></div>\n      </div>\n    </div>\n  </div>\n</div>\n\n<script nonce=\"__SESSION_TOKEN__\">\n  const SESSION_TOKEN = '__SESSION_TOKEN__';\n  let currentFile = null;\n  let lastZip = null;\n  let currentEnvSnapshot = null;\n  let currentGraphData = null;\n  let currentSelectedPath = null;\n  let showingMermaidSource = false;\n\n  function switchTab(tab) {\n    var tabs = ['skills', 'convert', 'search', 'graph', 'env'];\n    for (var i = 0; i < tabs.length; i++) {\n      var t = tabs[i];\n      var el = document.getElementById('panel-' + t);\n      if (el) el.style.display = (t === tab ? 'block' : 'none');\n    }\n\n    var allBtns = document.querySelectorAll('.tab-btn');\n    for (var j = 0; j < allBtns.length; j++) {\n      allBtns[j].classList.remove('active');\n    }\n    \n    var activeBtnMap = {\n      skills: 'tabBtnSkills',\n      convert: 'tabBtnConvert',\n      search: 'tabBtnSearch',\n      graph: 'tabBtnGraph',\n      env: 'tabBtnEnv'\n    };\n    var activeId = activeBtnMap[tab];\n    if (activeId) {\n      var activeEl = document.getElementById(activeId);\n      if (activeEl) activeEl.classList.add('active');\n    }\n\n    if (tab === 'env' && !currentEnvSnapshot) detectEnv();\n    if (tab === 'graph' && !currentGraphData) loadGraph();\n  }\n\n  function showStatus(elemId, type, msg) {\n    var el = document.getElementById(elemId);\n    if (!el) return;\n    el.className = 'status show ' + type;\n    el.textContent = msg;\n  }\n  function hideStatus(elemId) {\n    var el = document.getElementById(elemId);\n    if (el) el.className = 'status';\n  }\n\n  function escapeHtml(str) {\n    return (str || '')\n      .replace(/&/g, '&amp;')\n      .replace(/</g, '&lt;')\n      .replace(/>/g, '&gt;')\n      .replace(/\"/g, '&quot;')\n      .replace(/'/g, '&#039;');\n  }\n\n  function handleFile(file) {\n    if (!file) return;\n    currentFile = file;\n    document.getElementById('fileNameDisplay').textContent = '已选择: ' + file.name + ' (' + (file.size/1024).toFixed(1) + ' KB)';\n  }\n\n  function getLocalModelName() {\n    var sel = document.getElementById('localModelSelect');\n    var inp = document.getElementById('localModelInput');\n    if (sel && sel.style.display !== 'none' && sel.value) return sel.value.trim();\n    return inp ? inp.value.trim() : '';\n  }\n\n  function getLocalBaseUrl() {\n    var el = document.getElementById('localBaseUrl');\n    return el ? el.value.trim() : '';\n  }\n\n  function setupEvents() {\n    // 1. Tab 切换\n    var btnSkills = document.getElementById('tabBtnSkills');\n    var btnConvert = document.getElementById('tabBtnConvert');\n    var btnSearch = document.getElementById('tabBtnSearch');\n    var btnGraph = document.getElementById('tabBtnGraph');\n    var btnEnv = document.getElementById('tabBtnEnv');\n\n    if (btnSkills) btnSkills.addEventListener('click', function() { switchTab('skills'); });\n    if (btnConvert) btnConvert.addEventListener('click', function() { switchTab('convert'); });\n    if (btnSearch) btnSearch.addEventListener('click', function() { switchTab('search'); });\n    if (btnGraph) btnGraph.addEventListener('click', function() { switchTab('graph'); });\n    if (btnEnv) btnEnv.addEventListener('click', function() { switchTab('env'); });\n\n    // 2. 上传区\n    var uploadZone = document.getElementById('uploadZone');\n    var fileInput = document.getElementById('fileInput');\n    if (uploadZone && fileInput) {\n      uploadZone.addEventListener('click', function() { fileInput.click(); });\n      fileInput.addEventListener('change', function(e) { if (e.target.files.length) handleFile(e.target.files[0]); });\n\n      ['dragenter', 'dragover'].forEach(function(name) {\n        uploadZone.addEventListener(name, function(e) { e.preventDefault(); uploadZone.classList.add('dragover'); });\n      });\n      ['dragleave', 'drop'].forEach(function(name) {\n        uploadZone.addEventListener(name, function(e) { e.preventDefault(); uploadZone.classList.remove('dragover'); });\n      });\n      uploadZone.addEventListener('drop', function(e) {\n        if (e.dataTransfer.files.length) handleFile(e.dataTransfer.files[0]);\n      });\n    }\n\n    // 3. 技能工坊\n    var modelSelect = document.getElementById('modelSelect');\n    var detectBtn = document.getElementById('detectBtn');\n    var generateBtn = document.getElementById('generateBtn');\n    var evalSkillBtn = document.getElementById('evalSkillBtn');\n    var downloadZipBtn = document.getElementById('downloadZipBtn');\n    var copySkillBtn = document.getElementById('copySkillBtn');\n\n    if (modelSelect) modelSelect.addEventListener('change', onModelChange);\n    if (detectBtn) detectBtn.addEventListener('click', detectLocalModels);\n    if (generateBtn) generateBtn.addEventListener('click', generateSkill);\n    if (evalSkillBtn) evalSkillBtn.addEventListener('click', evaluateCurrentSkill);\n    if (downloadZipBtn) downloadZipBtn.addEventListener('click', triggerDownload);\n    if (copySkillBtn) copySkillBtn.addEventListener('click', copySkillContent);\n\n    // 4. 规则互转\n    var startConvertBtn = document.getElementById('startConvertBtn');\n    var syncProjectBtn = document.getElementById('syncProjectBtn');\n    var copyConvertBtn = document.getElementById('copyConvertBtn');\n\n    if (startConvertBtn) startConvertBtn.addEventListener('click', executeConvert);\n    if (syncProjectBtn) syncProjectBtn.addEventListener('click', executeSyncProject);\n    if (copyConvertBtn) copyConvertBtn.addEventListener('click', function() {\n      navigator.clipboard.writeText(document.getElementById('convertPreview').textContent);\n      alert('已复制转换结果！');\n    });\n\n    // 5. 搜索与影响面\n    var rebuildIndexBtn = document.getElementById('rebuildIndexBtn');\n    var searchBtn = document.getElementById('searchBtn');\n    var impactBtn = document.getElementById('impactBtn');\n    var searchQueryInput = document.getElementById('searchQueryInput');\n\n    if (rebuildIndexBtn) rebuildIndexBtn.addEventListener('click', buildCodeIndex);\n    if (searchBtn) searchBtn.addEventListener('click', executeSearch);\n    if (impactBtn) impactBtn.addEventListener('click', executeImpactAnalysis);\n    if (searchQueryInput) {\n      searchQueryInput.addEventListener('keydown', function(e) {\n        if (e.key === 'Enter') executeSearch();\n      });\n    }\n\n    document.querySelectorAll('.quick-tag').forEach(function(tag) {\n      tag.addEventListener('click', function() {\n        var filter = tag.getAttribute('data-filter');\n        var input = document.getElementById('searchQueryInput');\n        if (input && filter) {\n          input.value = (input.value.trim() + ' ' + filter).trim();\n          input.focus();\n        }\n      });\n    });\n\n    // 6. 图谱交互与事件委托 (Event Delegation)\n    var refreshGraphBtn = document.getElementById('refreshGraphBtn');\n    var toggleGraphViewBtn = document.getElementById('toggleGraphViewBtn');\n    var copyMermaidBtn = document.getElementById('copyMermaidBtn');\n    var closeDetailBtn = document.getElementById('closeDetailBtn');\n    var copySourceCodeBtn = document.getElementById('copySourceCodeBtn');\n    var trackImpactFromGraphBtn = document.getElementById('trackImpactFromGraphBtn');\n\n    if (refreshGraphBtn) refreshGraphBtn.addEventListener('click', loadGraph);\n    if (toggleGraphViewBtn) toggleGraphViewBtn.addEventListener('click', toggleGraphView);\n    if (copyMermaidBtn) copyMermaidBtn.addEventListener('click', function() {\n      navigator.clipboard.writeText(document.getElementById('graphMermaidCode').textContent);\n      alert('已复制 Mermaid 代码！');\n    });\n    if (closeDetailBtn) closeDetailBtn.addEventListener('click', function() {\n      document.getElementById('nodeDetailCard').style.display = 'none';\n      currentSelectedPath = null;\n      document.querySelectorAll('.node-item').forEach(function(n) {\n        n.classList.remove('selected', 'dep-node', 'upstream-node');\n      });\n      document.querySelectorAll('.module-card').forEach(function(c) {\n        c.classList.remove('dimmed', 'highlighted');\n      });\n    });\n\n    if (copySourceCodeBtn) copySourceCodeBtn.addEventListener('click', function() {\n      navigator.clipboard.writeText(document.getElementById('sourceCodeViewer').textContent);\n      alert('已复制文件源码！');\n    });\n\n    if (trackImpactFromGraphBtn) trackImpactFromGraphBtn.addEventListener('click', function() {\n      if (!currentSelectedPath) return;\n      switchTab('search');\n      var searchInput = document.getElementById('searchQueryInput');\n      if (searchInput) searchInput.value = currentSelectedPath;\n      executeImpactAnalysis();\n    });\n\n    // 事件委托：模块网格点击\n    var visualContainer = document.getElementById('visualModulesContainer');\n    if (visualContainer) {\n      visualContainer.addEventListener('click', function(e) {\n        var nodeItem = e.target.closest('.node-item');\n        if (nodeItem) {\n          var p = nodeItem.getAttribute('data-path');\n          if (p) selectNode(p);\n        }\n      });\n    }\n\n    // 事件委托：依赖药丸点击\n    var detailBox = document.getElementById('nodeDetailCard');\n    if (detailBox) {\n      detailBox.addEventListener('click', function(e) {\n        var pill = e.target.closest('.link-pill');\n        if (pill) {\n          var p = pill.getAttribute('data-path');\n          if (p) selectNode(p);\n        }\n      });\n    }\n\n    // 7. 环境资产\n    var refreshEnvBtn = document.getElementById('refreshEnvBtn');\n    var exportEnvBtn = document.getElementById('exportEnvBtn');\n    var diffEnvBtn = document.getElementById('diffEnvBtn');\n\n    if (refreshEnvBtn) refreshEnvBtn.addEventListener('click', detectEnv);\n    if (exportEnvBtn) exportEnvBtn.addEventListener('click', exportEnvSnapshot);\n    if (diffEnvBtn) diffEnvBtn.addEventListener('click', executeEnvDiff);\n  }\n\n  async function init() {\n    setupEvents();\n\n    try {\n      var mRes = await fetch('/api/models');\n      var mData = await mRes.json();\n      var mSelect = document.getElementById('modelSelect');\n      if (mSelect && mData.models) {\n        mSelect.innerHTML = '';\n        mData.models.forEach(function(m) {\n          var opt = document.createElement('option');\n          opt.value = m.id;\n          opt.textContent = m.name;\n          if (m.id === mData.defaultModel) opt.selected = true;\n          mSelect.appendChild(opt);\n        });\n        onModelChange();\n      }\n\n      var tRes = await fetch('/api/templates');\n      var tData = await tRes.json();\n      var tSelect = document.getElementById('templateSelect');\n      if (tSelect && tData.templates) {\n        tData.templates.forEach(function(t) {\n          var opt = document.createElement('option');\n          opt.value = t.id;\n          opt.textContent = t.name + ' (' + t.id + ')';\n          tSelect.appendChild(opt);\n        });\n      }\n    } catch (e) {\n      console.error('初始化数据加载失败:', e);\n    }\n  }\n\n  function onModelChange() {\n    var modelSelect = document.getElementById('modelSelect');\n    if (!modelSelect) return;\n    var model = modelSelect.value;\n    var isLocal = model.indexOf('local') !== -1;\n    var localCfg = document.getElementById('localConfig');\n    var apiGrp = document.getElementById('apiKeyGroup');\n    if (localCfg) localCfg.style.display = isLocal ? 'block' : 'none';\n    if (apiGrp) apiGrp.style.display = isLocal ? 'none' : 'block';\n  }\n\n  async function detectLocalModels() {\n    var base = document.getElementById('localBaseUrl').value;\n    var btn = document.getElementById('detectBtn');\n    if (btn) { btn.disabled = true; btn.textContent = '探测中...'; }\n    try {\n      var res = await fetch('/api/local-models', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json', 'X-DevToolkit-Token': SESSION_TOKEN },\n        body: JSON.stringify({ baseUrl: base })\n      });\n      var data = await res.json();\n      if (data.models && data.models.length) {\n        var sel = document.getElementById('localModelSelect');\n        if (sel) {\n          sel.innerHTML = '';\n          data.models.forEach(function(m) {\n            var opt = document.createElement('option');\n            opt.value = m.id;\n            opt.textContent = m.name;\n            sel.appendChild(opt);\n          });\n          sel.style.display = 'block';\n          var inp = document.getElementById('localModelInput');\n          if (inp) inp.style.display = 'none';\n        }\n      }\n    } catch (e) {\n      alert('探测失败: ' + e.message);\n    } finally {\n      if (btn) { btn.disabled = false; btn.textContent = '🔍 探测模型'; }\n    }\n  }\n\n  async function generateSkill() {\n    hideStatus('skillStatus');\n    var btn = document.getElementById('generateBtn');\n    if (btn) { btn.disabled = true; btn.textContent = '⏳ 正在提炼生成技能包...'; }\n\n    try {\n      var formData = new FormData();\n      if (currentFile) {\n        formData.append('file', currentFile);\n        formData.append('fileName', currentFile.name);\n      } else {\n        var src = document.getElementById('sourceInput').value.trim();\n        if (!src) throw new Error('请提供文档内容、URL 或上传文件');\n        formData.append('source', src);\n      }\n      var selectedModel = document.getElementById('modelSelect').value;\n      formData.append('agentType', document.getElementById('agentType').value);\n      formData.append('modelName', selectedModel);\n      formData.append('apiKey', document.getElementById('apiKeyInput').value);\n      formData.append('template', document.getElementById('templateSelect').value);\n      formData.append('skillName', document.getElementById('skillNameInput').value);\n\n      if (selectedModel.indexOf('local') !== -1) {\n        var localBase = getLocalBaseUrl();\n        var localName = getLocalModelName();\n        if (localBase) formData.append('localBaseUrl', localBase);\n        if (localName) formData.append('localModelName', localName);\n      }\n\n      var res = await fetch('/api/generate', {\n        method: 'POST',\n        headers: { 'X-DevToolkit-Token': SESSION_TOKEN },\n        body: formData\n      });\n      var data = await res.json();\n      if (!res.ok) throw new Error(data.error || '生成失败');\n\n      showStatus('skillStatus', 'success', '✨ 技能包提炼完成！');\n      document.getElementById('skillResultCard').style.display = 'block';\n      document.getElementById('skillContentPreview').textContent = data.content;\n      lastZip = data.zip;\n\n      var statsEl = document.getElementById('skillStats');\n      if (statsEl) {\n        statsEl.innerHTML = '<div class=\"stat-card\"><div class=\"label\">目标 Agent</div><div class=\"num\" style=\"font-size:16px\">' + data.agentType + '</div></div>' +\n          '<div class=\"stat-card\"><div class=\"label\">产物大小</div><div class=\"num\">' + data.size + ' 字符</div></div>' +\n          '<div class=\"stat-card\"><div class=\"label\">质量得分</div><div class=\"num\" style=\"color:var(--green)\">' + (data.quality ? data.quality.score : 100) + ' 分</div></div>';\n      }\n    } catch (e) {\n      showStatus('skillStatus', 'error', e.message);\n    } finally {\n      if (btn) { btn.disabled = false; btn.textContent = '🚀 开始提炼技能包'; }\n    }\n  }\n\n  async function evaluateCurrentSkill() {\n    hideStatus('skillStatus');\n    var content = document.getElementById('skillContentPreview').textContent;\n    if (!content) {\n      showStatus('skillStatus', 'error', '请先提炼生成技能包');\n      return;\n    }\n\n    var btn = document.getElementById('evalSkillBtn');\n    if (btn) { btn.disabled = true; btn.textContent = '⏳ 正在并发进行 Benchmark 评测...'; }\n    try {\n      var selectedModel = document.getElementById('modelSelect').value;\n      var evalPayload = {\n        skillContent: content,\n        model: selectedModel,\n        apiKey: document.getElementById('apiKeyInput').value\n      };\n      if (selectedModel.indexOf('local') !== -1) {\n        evalPayload.baseURL = getLocalBaseUrl() || undefined;\n        evalPayload.localModelName = getLocalModelName() || undefined;\n      }\n\n      var res = await fetch('/api/eval', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json', 'X-DevToolkit-Token': SESSION_TOKEN },\n        body: JSON.stringify(evalPayload)\n      });\n      var data = await res.json();\n      if (!res.ok) throw new Error(data.error || '评测执行失败');\n\n      var card = document.getElementById('skillEvalCard');\n      card.style.display = 'block';\n      document.getElementById('skillEvalPreview').textContent = data.markdown;\n      card.scrollIntoView({ behavior: 'smooth', block: 'nearest' });\n      showStatus('skillStatus', 'success', '✨ Benchmark 自动化评测完成！综合得分: ' + data.report.overallScore + ' 分 (' + data.report.grade + ' 级)');\n    } catch (e) {\n      showStatus('skillStatus', 'error', '评测失败: ' + e.message);\n    } finally {\n      if (btn) { btn.disabled = false; btn.textContent = '📊 技能效果自动化评测'; }\n    }\n  }\n\n  async function executeConvert() {\n    hideStatus('convertStatus');\n    var content = document.getElementById('convertInput').value.trim();\n    if (!content) return showStatus('convertStatus', 'error', '请粘贴要转换的规则内容');\n\n    try {\n      var res = await fetch('/api/convert', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json', 'X-DevToolkit-Token': SESSION_TOKEN },\n        body: JSON.stringify({\n          content: content,\n          to: document.getElementById('convertToSelect').value,\n          name: document.getElementById('convertNameInput').value.trim() || undefined\n        })\n      });\n      var data = await res.json();\n      if (!res.ok) throw new Error(data.error);\n\n      showStatus('convertStatus', 'success', '✨ 规则转换成功！');\n      document.getElementById('convertResultCard').style.display = 'block';\n      document.getElementById('convertPreview').textContent = data.preview;\n    } catch (e) {\n      showStatus('convertStatus', 'error', e.message);\n    }\n  }\n\n  async function executeSyncProject() {\n    showStatus('convertStatus', 'info', '正在自动扫描项目全部规则并分发...');\n    try {\n      var res = await fetch('/api/sync', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json', 'X-DevToolkit-Token': SESSION_TOKEN },\n        body: JSON.stringify({ dryRun: false })\n      });\n      var data = await res.json();\n      if (!res.ok) throw new Error(data.error);\n\n      showStatus('convertStatus', 'success', '✨ 项目全量规则同步完成！共分发 ' + data.summary.totalSynced + ' 项产物。');\n    } catch (e) {\n      showStatus('convertStatus', 'error', e.message);\n    }\n  }\n\n  function triggerDownload() {\n    if (!lastZip || !lastZip.id) return alert('未找到可下载的 ZIP 产物');\n    window.location.href = '/api/download/' + lastZip.id;\n  }\n\n  function copySkillContent() {\n    navigator.clipboard.writeText(document.getElementById('skillContentPreview').textContent);\n    alert('已复制到剪贴板！');\n  }\n\n  async function executeSearch() {\n    hideStatus('searchStatus');\n    var query = document.getElementById('searchQueryInput').value.trim();\n    if (!query) return showStatus('searchStatus', 'error', '请输入搜索内容');\n\n    var btn = document.getElementById('searchBtn');\n    if (btn) { btn.disabled = true; btn.textContent = '搜索中...'; }\n\n    try {\n      var res = await fetch('/api/search', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json', 'X-DevToolkit-Token': SESSION_TOKEN },\n        body: JSON.stringify({\n          query: query,\n          directory: document.getElementById('searchDirInput').value.trim() || undefined,\n          explain: document.getElementById('searchExplainCheck').checked\n        })\n      });\n      var data = await res.json();\n      if (!res.ok) throw new Error(data.error || '搜索失败');\n\n      if (data.explanation) {\n        document.getElementById('searchExplainCard').style.display = 'block';\n        document.getElementById('searchExplanation').textContent = data.explanation;\n      } else {\n        document.getElementById('searchExplainCard').style.display = 'none';\n      }\n\n      var area = document.getElementById('searchResultsArea');\n      area.innerHTML = '';\n      if (!data.results || data.results.length === 0) {\n        area.innerHTML = '<div class=\"card\" style=\"text-align:center; color:var(--text-muted)\">未找到匹配的代码片段</div>';\n        return;\n      }\n\n      data.results.forEach(function(r) {\n        var item = document.createElement('div');\n        item.className = 'search-item';\n        item.innerHTML = '<div class=\"search-item-header\">' +\n          '<div class=\"file-badge\">📄 ' + r.file + ' :' + r.startLine + '-' + r.endLine + '</div>' +\n          '<div class=\"score-badge\">相关度: ' + (r.score * 100).toFixed(0) + '%</div>' +\n          '</div>' +\n          '<div style=\"margin-bottom:10px;\">' +\n          r.matchedSymbols.map(function(s) { return '<span class=\"tag\" style=\"color:var(--accent-hover);\">' + s + '</span>'; }).join('') +\n          r.matchedKeywords.map(function(k) { return '<span class=\"tag\">' + k + '</span>'; }).join('') +\n          '</div>' +\n          '<div class=\"code-box\" style=\"max-height:220px;\">' + escapeHtml(r.content) + '</div>';\n        area.appendChild(item);\n      });\n    } catch (e) {\n      showStatus('searchStatus', 'error', e.message);\n    } finally {\n      if (btn) { btn.disabled = false; btn.textContent = '🔎 搜索代码'; }\n    }\n  }\n\n  async function executeImpactAnalysis() {\n    var file = document.getElementById('searchQueryInput').value.trim() || document.getElementById('searchDirInput').value.trim();\n    if (!file) return alert('请在搜索框输入要分析的目标文件路径（如 src/utils/logger.ts）');\n\n    showStatus('searchStatus', 'info', '正在推演改动影响链路...');\n    try {\n      var res = await fetch('/api/impact', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json', 'X-DevToolkit-Token': SESSION_TOKEN },\n        body: JSON.stringify({ targetFile: file })\n      });\n      var data = await res.json();\n      if (!res.ok) throw new Error(data.error);\n\n      document.getElementById('impactResultCard').style.display = 'block';\n      document.getElementById('impactReportText').textContent = data.report;\n      hideStatus('searchStatus');\n    } catch (e) {\n      showStatus('searchStatus', 'error', e.message);\n    }\n  }\n\n  async function loadGraph() {\n    showStatus('graphStatus', 'info', '正在构建代码架构拓扑图...');\n    try {\n      var res = await fetch('/api/graph', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json', 'X-DevToolkit-Token': SESSION_TOKEN },\n        body: JSON.stringify({})\n      });\n      var data = await res.json();\n      if (!res.ok) throw new Error(data.error);\n      hideStatus('graphStatus');\n      currentGraphData = data.graph;\n\n      var s = data.graph.stats;\n      document.getElementById('graphStats').innerHTML =\n        '<div class=\"stat-card\"><div class=\"label\">源码文件数</div><div class=\"num\">' + s.totalFiles + '</div></div>' +\n        '<div class=\"stat-card\"><div class=\"label\">依赖引用边</div><div class=\"num\" style=\"color:var(--accent)\">' + s.totalEdges + '</div></div>' +\n        '<div class=\"stat-card\"><div class=\"label\">独立模块数</div><div class=\"num\">' + s.isolatedFiles + '</div></div>';\n\n      document.getElementById('graphMermaidCode').textContent = data.mermaid;\n\n      renderVisualModules(data.graph);\n    } catch (e) {\n      showStatus('graphStatus', 'error', e.message);\n    }\n  }\n\n  function renderVisualModules(graph) {\n    var container = document.getElementById('visualModulesContainer');\n    if (!container) return;\n    container.innerHTML = '';\n\n    var modules = {};\n    Object.keys(graph.nodes).forEach(function(path) {\n      var parts = path.split('/');\n      var mod = parts.length > 1 ? parts.slice(0, 2).join('/') : 'root';\n      if (!modules[mod]) modules[mod] = [];\n      modules[mod].push(path);\n    });\n\n    Object.keys(modules).sort().forEach(function(mod) {\n      var card = document.createElement('div');\n      card.className = 'module-card';\n      card.setAttribute('data-module', mod);\n      var html = '<div class=\"module-header\"><span>📁 ' + mod + '</span><span style=\"font-size:11px; font-weight:normal; color:var(--text-muted);\">' + modules[mod].length + ' 个文件</span></div>';\n      \n      modules[mod].forEach(function(filePath) {\n        var fileName = filePath.split('/').pop() || filePath;\n        var outDeg = (graph.dependencies[filePath] || []).length;\n        var inDeg = (graph.dependents[filePath] || []).length;\n        html += '<div class=\"node-item\" data-path=\"' + filePath + '\">' +\n          '<span style=\"color:#fff;\">' + fileName + '</span>' +\n          '<span style=\"font-size:10px; color:var(--text-muted);\">出 ' + outDeg + ' | 入 ' + inDeg + '</span>' +\n          '</div>';\n      });\n\n      card.innerHTML = html;\n      container.appendChild(card);\n    });\n  }\n\n  async function selectNode(path) {\n    if (!currentGraphData) return;\n    currentSelectedPath = path;\n\n    var deps = currentGraphData.dependencies[path] || [];\n    var upstreams = currentGraphData.dependents[path] || [];\n    var relatedSet = new Set([path, ...deps, ...upstreams]);\n\n    // 1. 高亮与淡化处理\n    document.querySelectorAll('.node-item').forEach(function(n) {\n      var p = n.getAttribute('data-path');\n      n.classList.remove('selected', 'dep-node', 'upstream-node');\n      if (p === path) {\n        n.classList.add('selected');\n      } else if (deps.indexOf(p) !== -1) {\n        n.classList.add('dep-node');\n      } else if (upstreams.indexOf(p) !== -1) {\n        n.classList.add('upstream-node');\n      }\n    });\n\n    document.querySelectorAll('.module-card').forEach(function(c) {\n      var hasRelated = Array.from(c.querySelectorAll('.node-item')).some(function(n) {\n        return relatedSet.has(n.getAttribute('data-path'));\n      });\n      if (hasRelated) {\n        c.classList.remove('dimmed');\n        c.classList.add('highlighted');\n      } else {\n        c.classList.add('dimmed');\n        c.classList.remove('highlighted');\n      }\n    });\n\n    // 2. 渲染可点击跳转的依赖标签\n    document.getElementById('detailNodeTitle').textContent = '📄 ' + path;\n    \n    var depsPillsEl = document.getElementById('detailDepsPills');\n    if (depsPillsEl) {\n      if (deps.length > 0) {\n        depsPillsEl.innerHTML = deps.map(function(d) {\n          return '<span class=\"link-pill\" data-path=\"' + d + '\">➜ ' + d + '</span>';\n        }).join('');\n      } else {\n        depsPillsEl.innerHTML = '<span style=\"font-size:12px; color:var(--text-muted);\">无内部依赖 (叶子模块)</span>';\n      }\n    }\n\n    var upstreamsPillsEl = document.getElementById('detailUpstreamsPills');\n    if (upstreamsPillsEl) {\n      if (upstreams.length > 0) {\n        upstreamsPillsEl.innerHTML = upstreams.map(function(u) {\n          return '<span class=\"link-pill\" style=\"background:rgba(168,85,247,0.15); color:var(--purple); border-color:rgba(168,85,247,0.3);\" data-path=\"' + u + '\">⬅ ' + u + '</span>';\n        }).join('');\n      } else {\n        upstreamsPillsEl.innerHTML = '<span style=\"font-size:12px; color:var(--text-muted);\">顶层入口 / 无上游调用方</span>';\n      }\n    }\n\n    // 3. 异步读取并展示文件源码\n    var viewerEl = document.getElementById('sourceCodeViewer');\n    if (viewerEl) {\n      viewerEl.textContent = '正在读取文件源码...';\n      document.getElementById('nodeDetailCard').style.display = 'block';\n      document.getElementById('nodeDetailCard').scrollIntoView({ behavior: 'smooth', block: 'nearest' });\n\n      try {\n        var res = await fetch('/api/file/read', {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json', 'X-DevToolkit-Token': SESSION_TOKEN },\n          body: JSON.stringify({ path: path })\n        });\n        var data = await res.json();\n        if (!res.ok) throw new Error(data.error);\n\n        document.getElementById('detailFileStats').textContent = '(' + data.lines + ' 行代码 | ' + (data.size/1024).toFixed(1) + ' KB)';\n        viewerEl.textContent = data.content;\n      } catch (e) {\n        viewerEl.textContent = '无法读取源码: ' + e.message;\n      }\n    }\n  }\n\n  function toggleGraphView() {\n    showingMermaidSource = !showingMermaidSource;\n    var visual = document.getElementById('visualModulesContainer');\n    var source = document.getElementById('mermaidSourceContainer');\n    var btn = document.getElementById('toggleGraphViewBtn');\n\n    if (showingMermaidSource) {\n      if (visual) visual.style.display = 'none';\n      if (source) source.style.display = 'block';\n      if (btn) btn.textContent = '🎨 切换为交互式拓扑大盘';\n    } else {\n      if (visual) visual.style.display = 'grid';\n      if (source) source.style.display = 'none';\n      if (btn) btn.textContent = '📝 切换为 Mermaid 源码';\n    }\n  }\n\n  async function buildCodeIndex() {\n    showStatus('searchStatus', 'info', '正在扫描并重建索引...');\n    try {\n      var res = await fetch('/api/search/index', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json', 'X-DevToolkit-Token': SESSION_TOKEN },\n        body: JSON.stringify({ directory: document.getElementById('searchDirInput').value.trim() || undefined })\n      });\n      var data = await res.json();\n      if (!res.ok) throw new Error(data.error);\n      showStatus('searchStatus', 'success', '索引构建完成: ' + data.stats.totalFiles + ' 文件 / ' + data.stats.totalLines + ' 行 / ' + data.stats.totalChunks + ' 分块');\n    } catch (e) {\n      showStatus('searchStatus', 'error', e.message);\n    }\n  }\n\n  async function detectEnv() {\n    showStatus('envStatus', 'info', '正在扫描当前环境资产...');\n    try {\n      var res = await fetch('/api/env/detect', {\n        method: 'POST',\n        headers: { 'X-DevToolkit-Token': SESSION_TOKEN }\n      });\n      var data = await res.json();\n      if (!res.ok) throw new Error(data.error);\n      currentEnvSnapshot = data.snapshot;\n      hideStatus('envStatus');\n\n      var sys = data.snapshot.system;\n      document.getElementById('envSystemStats').innerHTML =\n        '<div class=\"stat-card\"><div class=\"label\">操作系统</div><div class=\"num\" style=\"font-size:15px\">' + sys.platform + ' (' + sys.arch + ')</div></div>' +\n        '<div class=\"stat-card\"><div class=\"label\">主机名</div><div class=\"num\" style=\"font-size:15px\">' + sys.hostname + '</div></div>' +\n        '<div class=\"stat-card\"><div class=\"label\">当前用户</div><div class=\"num\" style=\"font-size:15px\">' + sys.username + '</div></div>' +\n        '<div class=\"stat-card\"><div class=\"label\">默认 Shell</div><div class=\"num\" style=\"font-size:15px\">' + sys.shell + '</div></div>';\n\n      var brew = data.snapshot.brew || { formulae: [], casks: [] };\n      document.getElementById('envBrewList').innerHTML = brew.formulae.map(function(f) { return '🍺 ' + f; }).concat(brew.casks.map(function(c) { return '🍷 ' + c; })).join('<br>') || '无';\n\n      var npm = data.snapshot.npmGlobal || [];\n      document.getElementById('envNpmList').innerHTML = npm.map(function(n) { return n.name + ' <span style=\"color:var(--text-muted)\">@' + n.version + '</span>'; }).join('<br>') || '无';\n\n      var pip = data.snapshot.pipPackages || [];\n      document.getElementById('envPipList').innerHTML = pip.map(function(p) { return p.name + ' <span style=\"color:var(--text-muted)\">==' + p.version + '</span>'; }).join('<br>') || '无';\n\n      var vscode = data.snapshot.vscodeExtensions || [];\n      document.getElementById('envVscodeList').innerHTML = vscode.map(function(v) { return v.id + ' <span style=\"color:var(--text-muted)\">@' + v.version + '</span>'; }).join('<br>') || '无';\n    } catch (e) {\n      showStatus('envStatus', 'error', e.message);\n    }\n  }\n\n  function exportEnvSnapshot() {\n    if (!currentEnvSnapshot) return alert('请先扫描环境');\n    var blob = new Blob([JSON.stringify(currentEnvSnapshot, null, 2)], { type: 'application/json' });\n    var url = URL.createObjectURL(blob);\n    var a = document.createElement('a');\n    a.href = url;\n    a.download = 'devtoolkit-env.json';\n    a.click();\n  }\n\n  async function executeEnvDiff() {\n    var raw = document.getElementById('diffJsonInput').value.trim();\n    if (!raw) return alert('请粘贴快照 JSON 内容');\n    try {\n      var snap = JSON.parse(raw);\n      var res = await fetch('/api/env/diff', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json', 'X-DevToolkit-Token': SESSION_TOKEN },\n        body: JSON.stringify({ snapshot: snap })\n      });\n      var data = await res.json();\n      if (!res.ok) throw new Error(data.error);\n\n      document.getElementById('envDiffResult').style.display = 'block';\n      document.getElementById('envDiffPreview').textContent = data.preview;\n    } catch (e) {\n      alert('比对失败: ' + e.message);\n    }\n  }\n\n  // 保证无论页面何时加载完成都能立即挂载事件\n  if (document.readyState === 'loading') {\n    document.addEventListener('DOMContentLoaded', init);\n  } else {\n    init();\n  }\n</script>\n</body>\n</html>";
